(1242,2642,'Disease of the gastrointestinal tract.','en',2,'2026-06-30 10:39:58',NULL,NULL,'5614FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(1243,2645,'A form of bronchial disorder associated with airway obstruction, marked by recurrent attacks of paroxysmal dyspnea, with wheezing due to spasmodic contraction of the bronchi.','en',2,'2026-06-30 10:39:58',NULL,NULL,'5607FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
