(1390,2923,'Inflammation of the lining of the abdomen and pelvis.','en',2,'2026-06-30 10:40:06',NULL,NULL,'3953FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(1391,2924,'A major deviation from normal patterns of behavior.','en',2,'2026-06-30 10:40:06',NULL,NULL,'3950FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(1392,2928,'Inflammation of a vein associated with thrombus formation.','en',2,'2026-06-30 10:40:06',NULL,NULL,'3941FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
